package main

import (
	"bytes"
	"crypto/tls"
	"fmt"
	"log"
	"net"
	"net/http"
	"net/url"
	"os"
	"os/signal"
	"strconv"
	"syscall"

	"github.com/gorilla/websocket"
	"github.com/pelletier/go-toml/v2" // 替换为 v2 库以支持 comment tag
)

// ClientConfig 对应 settings.toml 的结构
type ClientConfig struct {
	LocalListen string `toml:"local_listen" comment:"本地 MC 客户端连接的 TCP 监听地址"`
	CdnWSURL    string `toml:"cdn_url" comment:"CDN 的 WebSocket 接入点 (如果 CDN 启用了 HTTPS/TLS，请用 wss://)"`
	SkipTLS     bool   `toml:"skip_tls" comment:"是否跳过 CDN 的 TLS 证书验证 (使用自签名证书时开启)"`
}

var globalConfig ClientConfig

const configFile = "settings.toml"

// FindAvailablePort 从指定端口开始向上寻找可用的 TCP 端口
func FindAvailablePort(host string, startPort int) (int, error) {
	for port := startPort; port <= 65535; port++ {
		addr := net.JoinHostPort(host, strconv.Itoa(port))
		listener, err := net.Listen("tcp", addr)
		if err == nil {
			err := listener.Close()
			if err != nil {
				return 0, err
			} // 关闭监听器，释放端口
			return port, nil
		}
	}
	return 0, fmt.Errorf("no available port found")
}

func main() {
	// 1. 检查并生成默认配置文件
	ensureConfigFile()

	// 2. 加载 TOML 配置文件
	fileBytes, err := os.ReadFile(configFile)
	if err != nil {
		log.Fatalf("[FATAL] 读取配置文件失败: %v", err)
	}
	if err := toml.Unmarshal(fileBytes, &globalConfig); err != nil {
		log.Fatalf("[FATAL] 解析配置文件失败: %v", err)
	}

	// 3. 智能端口检查与自动替换
	host, portStr, err := net.SplitHostPort(globalConfig.LocalListen)
	if err != nil {
		log.Fatalf("[FATAL] 解析 local_listen 地址格式失败 (形如 127.0.0.1:3001): %v", err)
	}
	startPort, err := strconv.Atoi(portStr)
	if err != nil {
		log.Fatalf("[FATAL] 解析端口号失败: %v", err)
	}

	// 寻找可用端口
	finalPort, err := FindAvailablePort(host, startPort)
	if err != nil {
		log.Fatalf("[FATAL] 无法找到可用的 TCP 端口: %v", err)
	}

	// 如果端口变了，更新全局变量并提示用户
	if finalPort != startPort {
		log.Printf("[WARN] 提示: 端口 %d 已被占用，自动切换至新端口 %d", startPort, finalPort)
		globalConfig.LocalListen = net.JoinHostPort(host, strconv.Itoa(finalPort))
	}

	// 4. 监听本地 TCP 端口
	listener, err := net.Listen("tcp", globalConfig.LocalListen)
	if err != nil {
		log.Fatalf("[FATAL] 本地 TCP 监听失败: %v", err)
	}
	defer listener.Close()

	log.Printf("[CLIENT] 客户端代理已启动！请在 MC 游戏中连接: %s", globalConfig.LocalListen)
	log.Printf("[CLIENT] 正在将流量转发至 CDN: %s", globalConfig.CdnWSURL)

	// 监听系统退出信号，优雅关闭
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-sigChan
		log.Println("[CLIENT] 正在关闭客户端代理...")
		listener.Close()
		os.Exit(0)
	}()

	// 5. 死循环接收来自 MC 游戏客户端的连接
	for {
		gameConn, err := listener.Accept()
		if err != nil {
			log.Printf("[WARN] 接收游戏客户端连接失败: %v", err)
			continue
		}

		// 异步处理每一个玩家的本地连接
		go handleGameConnection(gameConn)
	}
}

// ensureConfigFile 检查配置文件是否存在，若不存在则使用 v2 encoder 自动生成（含注释）
func ensureConfigFile() {
	if _, err := os.Stat(configFile); os.IsNotExist(err) {
		log.Printf("[INFO] 未检测到配置文件，正在生成默认的 %s ...", configFile)

		// 定义客户端默认配置
		defaultConfig := ClientConfig{
			LocalListen: "127.0.0.1:3001",
			CdnWSURL:    "ws://example.com:80/mc",
			SkipTLS:     false,
		}

		// 使用 bytes.Buffer 和 toml.NewEncoder 进行结构化序列化
		var buf bytes.Buffer
		encoder := toml.NewEncoder(&buf)

		// 编码执行后，v2 库会提取 struct 里的 comment tag 自动转化为 # 注释
		if err := encoder.Encode(defaultConfig); err != nil {
			log.Fatalf("[FATAL] 序列化默认配置失败: %v", err)
		}

		// 写入文件
		if err := os.WriteFile(configFile, buf.Bytes(), 0644); err != nil {
			log.Fatalf("[FATAL] 自动创建配置文件失败: %v", err)
		}

		log.Printf("[INFO] 默认配置文件生成成功，程序将使用默认参数继续启动。")
	}
}

func handleGameConnection(gameConn net.Conn) {
	defer gameConn.Close()

	// 1. 配置 WebSocket Dial
	u, err := url.Parse(globalConfig.CdnWSURL)
	if err != nil {
		log.Printf("[ERR] CDN URL 解析错误: %v", err)
		return
	}

	dialer := websocket.DefaultDialer
	if u.Scheme == "wss" && globalConfig.SkipTLS {
		dialer.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}

	requestHeader := make(http.Header)
	requestHeader.Set("referer", "https://toh-client.example.com")
	// 添加或修改 User-Agent
	requestHeader.Set("User-Agent", "toh-client")

	// 2. 连接到 CDN 节点
	log.Printf("[CONNECT] 收到游戏客户端连接，正在连接 CDN WebSocket...")
	wsConn, _, err := dialer.Dial(u.String(), requestHeader)

	if err != nil {
		log.Printf("[ERR] 无法连接到 CDN 节点 (%s): %v", u.String(), err)
		return
	}
	defer wsConn.Close()

	log.Printf("[SUCCESS] 隧道建立成功！流量已成功连接至 CDN。")

	// 3. 双向管道数据转发
	errChan := make(chan error, 2)

	// 协程 A: 将 MC 游戏客户端的 TCP 字节流 -> 打包发给 CDN WS
	go func() {
		buf := make([]byte, 32*1024)
		for {
			n, err := gameConn.Read(buf)
			if n > 0 {
				err = wsConn.WriteMessage(websocket.BinaryMessage, buf[:n])
				if err != nil {
					errChan <- err
					return
				}
			}
			if err != nil {
				errChan <- err
				return
			}
		}
	}()

	// 协程 B: 将来自 CDN WS 的数据 -> 解包发回给 MC 游戏客户端
	go func() {
		for {
			msgType, payload, err := wsConn.ReadMessage()
			if err != nil {
				errChan <- err
				return
			}
			if msgType == websocket.BinaryMessage || msgType == websocket.TextMessage {
				_, err = gameConn.Write(payload)
				if err != nil {
					errChan <- err
					return
				}
			}
		}
	}()

	<-errChan
	log.Printf("[DISCONNECT] 连接已断开。")
}

package main

import (
	"bytes"
	"encoding/binary"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"strings"

	"github.com/gorilla/websocket"
	"github.com/pelletier/go-toml/v2"
)

// Config 对应 settings.toml 的结构
type Config struct {
	Listen     string `toml:"listen" comment:"WS 代理监听地址 (接收来自 CDN 的连接)"`
	Path       string `toml:"path" comment:"WS 路由路径"`
	Backend    string `toml:"backend" comment:"MC 服务器真实的内网 TCP 地址"`
	Header     string `toml:"header" comment:"CDN 传递真实 IP 的 Header 名称 (例如 X-Forwarded-For 或 CF-Connecting-IP)"`
	PortHeader string `toml:"port_header" comment:"CDN 传递真实端口的 Header 名称 (留空则默认使用临时端口 50000)"`
	Password   string `toml:"password" comment:"安全校验密钥：CDN 请求必须携带 X-Toh-Token 且值匹配才允许连接 (留空则不校验)"`
}

var (
	globalConfig Config
	upgrader     = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true }, // 允许跨域（CDN 转发过来）
	}
)

const configFile = "settings.toml"

func main() {
	// 1. 检查并生成默认配置文件
	ensureConfigFile()

	// 2. 加载 TOML 配置文件
	fileBytes, err := os.ReadFile(configFile)
	if err != nil {
		log.Fatalf("[FATAL] 读取配置文件失败: %v", err)
	}
	if err := toml.Unmarshal(fileBytes, &globalConfig); err != nil {
		log.Fatalf("[FATAL] 解析配置文件失败: %v", err)
	}

	// 4. 启动服务
	http.HandleFunc(globalConfig.Path, handleWebSocket)

	log.Printf("[PROXY] 正在监听 WS: http://%s%s", globalConfig.Listen, globalConfig.Path)
	log.Printf("[PROXY] 后端 MC 服务端目标: %s", globalConfig.Backend)
	if globalConfig.Password != "" {
		log.Printf("[SECURITY] 已启用 X-Toh-Token 密码校验机制")
	}

	if err := http.ListenAndServe(globalConfig.Listen, nil); err != nil {
		log.Fatalf("[FATAL] 监听失败: %v", err)
	}
}

// ensureConfigFile 检查配置文件是否存在，若不存在则使用 v2 encoder 自动生成
func ensureConfigFile() {
	if _, err := os.Stat(configFile); os.IsNotExist(err) {
		log.Printf("[INFO] 未检测到配置文件，正在生成默认的 %s ...", configFile)

		// 定义默认结构体数据
		defaultConfig := Config{
			Listen:     ":8080",
			Path:       "/mc",
			Backend:    "127.0.0.1:25566",
			Header:     "X-Forwarded-For",
			PortHeader: "X-Forwarded-Port",
			Password:   "",
		}

		var buf bytes.Buffer
		encoder := toml.NewEncoder(&buf)

		if err := encoder.Encode(defaultConfig); err != nil {
			log.Fatalf("[FATAL] 序列化默认配置失败: %v", err)
		}

		if err := os.WriteFile(configFile, buf.Bytes(), 0644); err != nil {
			log.Fatalf("[FATAL] 自动创建配置文件失败: %v", err)
		}

		log.Printf("[INFO] 默认配置文件生成成功，程序将使用默认参数继续启动。")
	}
}

// 处理来自 CDN 的 WebSocket 请求
func mainHandler(w http.ResponseWriter, r *http.Request) {
	// 1. 安全校验：检查密码是否匹配
	if globalConfig.Password != "" {
		reqPassword := r.Header.Get("X-Toh-Token")
		if reqPassword != globalConfig.Password {
			log.Printf("[UNAUTHORIZED] 拒绝了来自 %s 的连接请求: X-Toh-Token 校验失败", r.RemoteAddr)
			http.Error(w, "401 Unauthorized: Invalid proxy password", http.StatusUnauthorized)
			return
		}
	}

	// 2. 升级为 WebSocket
	wsConn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("[ERR] WS 升级失败: %v", err)
		return
	}
	defer wsConn.Close()

	clientIP, clientPort := parseRealClientAddr(r)

	// 3. 连接到后端的 MC 服务器
	mcConn, err := net.Dial("tcp", globalConfig.Backend)
	if err != nil {
		log.Printf("[ERR] 无法连接到后端的 MC 服务器 (%s): %v", globalConfig.Backend, err)
		return
	}
	defer mcConn.Close()

	// 4. 构建并写入 PROXY Protocol v2 二进制头部给 MC 服务器
	pp2Header := buildProxyProtocolV2(clientIP, clientPort, mcConn.RemoteAddr().String())
	if _, err := mcConn.Write(pp2Header); err != nil {
		log.Printf("[ERR] 写入 PROXY v2 头部失败: %v", err)
		return
	}

	pipe(wsConn, mcConn)
}

// 兼容不同的 CDN Header 提取玩家真实 IP 与端口
func parseRealClientAddr(r *http.Request) (string, uint16) {
	ipStr, portStr, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		ipStr = r.RemoteAddr
		portStr = "50000"
	}

	if h := r.Header.Get(globalConfig.Header); h != "" {
		parts := strings.Split(h, ",")
		ipStr = strings.TrimSpace(parts[0])
	}

	if globalConfig.PortHeader != "" {
		if p := r.Header.Get(globalConfig.PortHeader); p != "" {
			portStr = p
		}
	}

	port, _ := strconv.Atoi(portStr)
	if port <= 0 || port > 65535 {
		port = 50000
	}

	return ipStr, uint16(port)
}

// 严格按照 HAProxy 规范构建 PROXY protocol v2 二进制数据包
func buildProxyProtocolV2(srcIPStr string, srcPort uint16, dstAddrStr string) []byte {
	signature := []byte("\x0D\x0A\x0D\x0A\x00\x0D\x0A\x51\x55\x49\x54\x0A")

	srcIP := net.ParseIP(srcIPStr)
	dstIPStr, dstPortStr, _ := net.SplitHostPort(dstAddrStr)
	dstIP := net.ParseIP(dstIPStr)
	dstPort, _ := strconv.Atoi(dstPortStr)

	var verCmd byte = 0x21
	var famProto byte = 0x11
	var addressLen uint16 = 12

	if srcIP.To4() == nil && srcIP.To16() != nil {
		famProto = 0x21
		addressLen = 36
	}

	headerLen := 12 + 1 + 1 + 2 + int(addressLen)
	buf := make([]byte, headerLen)

	copy(buf[0:12], signature)
	buf[12] = verCmd
	buf[13] = famProto
	binary.BigEndian.PutUint16(buf[14:16], addressLen)

	pos := 16
	if famProto == 0x11 {
		copy(buf[pos:pos+4], srcIP.To4())
		pos += 4
		copy(buf[pos:pos+4], dstIP.To4())
		pos += 4
	} else {
		copy(buf[pos:pos+16], srcIP.To16())
		pos += 16
		copy(buf[pos:pos+16], dstIP.To16())
		pos += 16
	}

	binary.BigEndian.PutUint16(buf[pos:pos+2], srcPort)
	pos += 2
	binary.BigEndian.PutUint16(buf[pos:pos+2], uint16(dstPort))

	return buf
}

// 桥接 WebSocket 和 TCP Socket 的流量
func pipe(wsConn *websocket.Conn, tcpConn net.Conn) {
	errChan := make(chan error, 2)

	go func() {
		for {
			msgType, payload, err := wsConn.ReadMessage()
			if err != nil {
				errChan <- err
				return
			}
			if msgType == websocket.BinaryMessage || msgType == websocket.TextMessage {
				_, err = tcpConn.Write(payload)
				if err != nil {
					errChan <- err
					return
				}
			}
		}
	}()

	go func() {
		buf := make([]byte, 32*1024)
		for {
			n, err := tcpConn.Read(buf)
			if n > 0 {
				err = wsConn.WriteMessage(websocket.BinaryMessage, buf[:n])
				if err != nil {
					errChan <- err
					return
				}
			}
			if err != nil {
				errChan <- err
				return
			}
		}
	}()

	<-errChan
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	mainHandler(w, r)
}
